import{_ as i,o as t,c as e,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2019-03-07 :: Ceph Developer Meeting","description":"","frontmatter":{"title":"2019-03-07 :: Ceph Developer Meeting","date":"2019-03-07T00:00:00.000Z","updated":"2019-04-15T00:00:00.000Z","tags":["Ceph","自动修复","分布式存储","副本池","平衡器模式","崩溃记录","媒体错误处理"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-03-07_-_-_Ceph_Developer_Meeting.md","filePath":"posts/2019/2019-03-07_-_-_Ceph_Developer_Meeting.md","lastUpdated":1780460162000}'),p={name:"posts/2019/2019-03-07_-_-_Ceph_Developer_Meeting.md"};function r(s,l,u,n,_,a){return t(),e("div",null,[...l[0]||(l[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2019年3月7日</p><p><strong>参会人员</strong>： [所有参会人员名单]</p><p><strong>会议主题</strong>： Ceph分布式存储系统改进与讨论</p><p><strong>会议内容</strong>：</p><p><strong>一、自动错误修复</strong></p><ul><li>目标：使系统能够自动修复其发现的错误，从而实现更少的手动干预。</li><li>讨论内容： <ul><li>自动修复的适用场景：由于外部因素（如介质错误、宇宙射线）或软件错误引起的错误。</li><li>自动修复的限制：除非我们知道如何修复错误，并且不需要从系统中获取任何信息，否则不应自动修复。</li><li>自动修复的实现：通过在OSD级别添加错误标志位，并根据错误标志位进行自动修复。</li><li>维护OSD级别统计数据：在超级块中添加字段或添加其他对象，以跟踪修复操作。</li></ul></li></ul><p><strong>二、副本池的自动修复</strong></p><ul><li>目标：为副本池实现自动修复功能。</li><li>讨论内容： <ul><li>当前实现：仅对记录池支持自动修复。</li><li>实现方案：将自动修复功能扩展到副本池，并在深度检查时进行修复。</li></ul></li></ul><p><strong>三、健康警报</strong></p><ul><li>目标：根据修复操作的结果，调整健康警报的严重程度。</li><li>讨论内容： <ul><li>修复失败：添加新的PG状态标志，用于表示修复失败。</li><li>健康警报级别：根据修复结果，调整健康警报的级别。</li></ul></li></ul><p><strong>四、平衡器模式</strong></p><ul><li>目标：为新的OSD设置默认的平衡器模式。</li><li>讨论内容： <ul><li>默认模式：将默认平衡器模式设置为Crush Compat模式，使新添加的OSD从零权重开始，逐渐增加权重。</li><li>测试与验证：需要对平衡器模式进行测试，以确保其正常工作。</li></ul></li></ul><p><strong>五、容器中的问题</strong></p><ul><li>讨论内容： <ul><li>gcore 和 pstack 在容器中不可用。</li><li>需要一种方法来获取容器中线程的堆栈跟踪。</li><li>可能在容器外部挂载调试工具，例如 GDB。</li></ul></li></ul><p><strong>六、崩溃记录</strong></p><ul><li>目标：记录崩溃信息，并生成健康警报。</li><li>讨论内容： <ul><li>崩溃记录：记录崩溃发生的时间、进程、堆栈跟踪等信息。</li><li>健康警报：根据崩溃记录，生成健康警报。</li><li>重复崩溃：针对重复崩溃的情况，生成更精确的健康警报。</li></ul></li></ul><p><strong>七、媒体错误处理</strong></p><ul><li>讨论内容： <ul><li>对于媒体错误，应尝试自动恢复，并避免崩溃。</li><li>可以通过设置特殊的退出代码，来避免系统B尝试重启。</li><li>可以记录崩溃报告，并添加注释，以便后续分析。</li></ul></li></ul><p><strong>八、其他</strong></p><ul><li>讨论内容： <ul><li>CephCon 会议。</li><li>容器中的问题。</li></ul></li></ul><p><strong>后续行动计划</strong>：</p><ul><li>完成自动修复功能的开发。</li><li>实现副本池的自动修复功能。</li><li>调整健康警报的严重程度。</li><li>测试和验证新的平衡器模式。</li><li>解决容器中的问题。</li><li>完成崩溃记录功能的开发。</li><li>改进媒体错误处理。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到的部分关键词，如 &quot;Crush Compat&quot;、&quot;OSD&quot;、&quot;PG&quot;、&quot;scrub&quot;、&quot;deep scrub&quot; 等，均为 Ceph 分布式存储系统中的关键术语。</li></ul>',25)])])}const c=i(p,[["render",r]]);export{d as __pageData,c as default};
